-- pintopets_vaccinations: tenant-scoped rows behind /vaccinations (generated by `opsapi make:resource`).
-- Runs once, inside a transaction. Never edit it after it has been applied —
-- add a new migration file instead.
return function(schema, db)
    db.query([[
        CREATE TABLE IF NOT EXISTS pintopets_vaccinations (
            id BIGSERIAL PRIMARY KEY,
            uuid UUID NOT NULL UNIQUE DEFAULT gen_random_uuid(),
            namespace_id INTEGER NOT NULL REFERENCES namespaces(id) ON DELETE CASCADE,
            pet_uuid UUID NOT NULL REFERENCES pintopets_pets(uuid) ON DELETE CASCADE,
            created_by_user_uuid UUID NOT NULL,
            vaccine VARCHAR(255) NOT NULL,
            given_on DATE NOT NULL,
            batch_number VARCHAR(255),
            vet VARCHAR(255),
            next_due_on DATE,
            notes TEXT,
            created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
            updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
        )
    ]])
    db.query("CREATE INDEX IF NOT EXISTS idx_pintopets_vaccinations_namespace ON pintopets_vaccinations (namespace_id, id DESC)")
    db.query("CREATE INDEX IF NOT EXISTS idx_pintopets_vaccinations_pet ON pintopets_vaccinations (namespace_id, pet_uuid)")
end
